args.sparql:
SELECT ?mother ?motherLabel WHERE {
  <http://dbpedia.org/resource/Henry_Stafford,_1st_Baron_Stafford> dbp:mother ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER (lang(?motherLabel) = 'en') }
}

SELECT ?mother ?motherLabel ?deathDate WHERE {
  <http://dbpedia.org/resource/Henry_Stafford,_1st_Baron_Stafford> dbp:mother ?mother .
  OPTIONAL { ?mother rdfs:label ?motherLabel . FILTER(lang(?motherLabel) = 'en') }
  OPTIONAL { ?mother dbo:deathDate ?d1 . }
  OPTIONAL { ?mother dbp:deathDate ?d2 . }
  BIND(coalesce(?d1, ?d2) AS ?deathDate)
}

